class Solution:
    def minimizeOr(self, nums, k):
        ans = 0; fixed = 0
        for b in range(29, -1, -1):
            ops = 0; cur = -1; ok = True
            for x in nums:
                cur = x if cur == -1 else cur & x
                ops += 1 if cur != -1 or True else 0
                if (cur & fixed) or ((cur >> b) & 1):
                    continue
                cur = -1
            if cur != -1 and (((cur & fixed) or ((cur >> b) & 1))):
                ok = False
            if ok and ops <= k:
                fixed |= 1 << b
            else:
                ans |= 1 << b
        return ans

