class Solution {
public:
    int minimizeOr(vector<int>& nums, int k) {
        int ans = 0, fixed = 0;
        for (int b = 29; b >= 0; b--) {
            long long ops = 0; int cur = -1; bool ok = true;
            for (int x : nums) {
                cur = (cur == -1) ? x : cur & x;
                ops++;
                if ((cur & fixed) || ((cur >> b) & 1)) continue;
                cur = -1;
            }
            if (cur != -1 && ((cur & fixed) || ((cur >> b) & 1))) ok = false;
            if (ok && ops <= k) fixed |= 1 << b;
            else ans |= 1 << b;
        }
        return ans;
    }
};

