var minimizeOr = function(nums, k) {
    let ans = 0, fixed = 0;
    for (let b = 29; b >= 0; b--) {
        let ops = 0, cur = -1, ok = true;
        for (const x of nums) {
            cur = cur === -1 ? x : cur & x;
            ops++;
            if ((cur & fixed) || ((cur >>> b) & 1)) continue;
            cur = -1;
        }
        if (cur !== -1 && ((cur & fixed) || ((cur >>> b) & 1))) ok = false;
        if (ok && ops <= k) fixed |= 1 << b;
        else ans |= 1 << b;
    }
    return ans;
};
